public int maximalSquare(char[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] dp = new int[m][n];
        int max = 0;
        for (int i = 0; i < m; i++) {
            dp[i][0] = matrix[i][0] == '1' ? 1 : 0;
            max = Math.max(max, dp[i][0]);
        }
        for (int j = 0; j < n; j++) {
            dp[0][j] = matrix[0][j] == '1' ? 1 : 0;
            max = Math.max(max, dp[0][j]);
        }
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] == '1') {
                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;
                } else {
                    dp[i][j] = 0;
                }
                max = Math.max(max, dp[i][j]);
            }
        }
        return max * max;
    }

public int maximalSquare(char[][] matrix) {
    int m = matrix.length;
    if (m == 0) {
        return 0;
    }
    int n = matrix[0].length;
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
        dp[i] = matrix[0][i] == '1' ? 1 : 0;
    }

    int max = 0;
    for (int i = 0; i < m; i++) {
        int leftTop = dp[0];
        for (int j = 0; j < n; j++) {
            int pre = dp[j];
            if (matrix[i][j] == '0') {
                dp[j] = 0;
            } else {
                if (i > 0 && j > 0) {
                    dp[j] = Math.min(dp[j - 1], Math.min(leftTop, pre)) + 1;
                } else {
                    dp[j] = 1;
                }
            }
            leftTop = pre;
            max = Math.max(max, dp[j]);
        }
    }
    return max * max;
}

